from itertools import product

def check_magic_sequence(seq):
    """Check if a sequence is a magic sequence."""
    for i in range(len(seq)):
        if seq[i] != seq.count(i):
            return False
    return True

# We need x[2] = 2
# Search for magic sequences of length 5 with x[2] = 2
for seq in product(range(6), repeat=5):
    if seq[2] == 2 and check_magic_sequence(seq):
        print(f"Found: {list(seq)}")
        # Verify
        for i in range(5):
            print(f"  x[{i}] = {seq[i]}, count of {i} = {seq.count(i)}")
